import * as T from 'three';
export function hmiGeometry({group,box,mesh,tube,updaters}){const g=group('hmi',[0,1.1,0]);box(.9,.15,.9,'dark',g,[4.35,.34,4.7]);box(.18,.8,.18,'steel',g,[4.35,.77,4.7]);box(2.35,1.5,.23,'dark',g,[4.35,1.82,4.7]);const c=document.createElement('canvas');c.width=768;c.height=448;const ctx=c.getContext('2d'),texture=new T.CanvasTexture(c);texture.colorSpace=T.SRGBColorSpace;const screen=mesh(new T.PlaneGeometry(2.14,1.25),'light',g,[4.35,1.82,4.83]);screen.material=new T.MeshBasicMaterial({map:texture,toneMapped:false});const wire=group('hmiCable');tube([[4.35,1.2,4.6],[4.35,.6,4.3],[2.1,.6,4.3],[2.1,.8,4.8]],.025,0x6a93ab,wire);let last='';
 updaters.push((m,e)=>{wire.visible=e<.02;const key=JSON.stringify([Math.round(m.x*100),Math.round(m.y*100),m.cycles,m.target,m.run,m.mode,m.fault]);if(key===last)return;last=key;ctx.fillStyle='#e7efdc';ctx.fillRect(0,0,768,448);ctx.fillStyle='#284b3c';ctx.fillRect(0,0,768,75);ctx.fillStyle='#f1f6e5';ctx.font='bold 32px monospace';ctx.fillText('HMI / PLC · '+(m.run?'RUN':'STOP'),25,49);for(const [i,label,x]of [[0,'A',m.x],[1,'B',m.y]]){const y=120+i*100;ctx.fillStyle='#294a34';ctx.font='bold 34px monospace';ctx.fillText(label+'  '+(x*100).toFixed(0)+' mm',26,y);ctx.fillStyle='#c3d2b7';ctx.fillRect(26,y+18,700,25);ctx.fillStyle='#729f49';ctx.fillRect(26,y+18,700*x,25);}ctx.fillStyle=m.fault?'#a35235':'#294a34';ctx.font='bold 31px monospace';ctx.fillText('C1  '+m.cycles+' / '+m.target+'   '+m.mode.toUpperCase(),26,342);ctx.fillText(m.fault?'ALARMA DE SENSOR':'SIN ALARMA ACTIVA',26,405);texture.needsUpdate=true;});
}
